1	import { CfnOutput, Duration, RemovalPolicy } from 'aws-cdk-lib';
2	import {
3	  Certificate,
4	  CertificateValidation,
5	} from 'aws-cdk-lib/aws-certificatemanager';
6	import {
7	  AllowedMethods,
8	  Distribution,
9	  HttpVersion,
10	  IDistribution,
11	  ResponseHeadersPolicy,
12	  SecurityPolicyProtocol,
13	  ViewerProtocolPolicy,
14	} from 'aws-cdk-lib/aws-cloudfront';
15	import { S3BucketOrigin } from 'aws-cdk-lib/aws-cloudfront-origins';
16	import {
17	  ARecord,
18	  HostedZone,
19	  IHostedZone,
20	  RecordTarget,
21	} from 'aws-cdk-lib/aws-route53';
22	import { CloudFrontTarget } from 'aws-cdk-lib/aws-route53-targets';
23	import { BlockPublicAccess, Bucket, IBucket } from 'aws-cdk-lib/aws-s3';
24	import {
25	  BucketDeployment,
26	  CacheControl,
27	  ISource,
28	  Source,
29	} from 'aws-cdk-lib/aws-s3-deployment';
30	import { Construct } from 'constructs';
31	
32	export interface SpaProps {
33	  domainName: string;
34	  buildOutputPath: string;
35	  bucketRemovalPolicy?: RemovalPolicy;
36	  extraAllowedOrigins?: string[];
37	  /**
38	   * Files that keep their names across releases, such as a service worker,
39	   * its ngsw.json or an import map, as globs relative to buildOutputPath.
40	   * They are served with no-cache instead of the one year max-age the hashed
41	   * bundles get, and are uploaded after those bundles.
42	   */
43	  noCacheFiles?: string[];
44	  /**
45	   * Files that get their own Cache-Control, and optionally Content-Type,
46	   * instead of the one year max-age, as globs relative to buildOutputPath.
47	   * Like noCacheFiles, they are left out of the main deployment and uploaded
48	   * after it, so each file is written once with one header. Keep the globs
49	   * of different entries disjoint: a file matched twice is uploaded twice and
50	   * the later header wins. `**` may only appear in the last segment.
51	   */
52	  cacheOverrides?: CacheOverride[];
53	}
54	
55	export interface CacheOverride {
56	  /** Globs relative to buildOutputPath, e.g. `assets/manifest*.json`. */
57	  files: string[];
58	  cacheControl: CacheControl;
59	  contentType?: string;
60	}
61	
62	/**
63	 * Exclude globs that keep only `files`. '**' also skips every folder as a
64	 * whole, so the folders above a nested file are re-included first, and
65	 * `<glob>/**` keeps the contents of a glob that names a folder.
66	 */
67	function onlyInclude(files: string[]): string[] {
68	  const included = new Set<string>();
69	  for (const file of files) {
70	    const folders = file.split('/').slice(0, -1);
71	    if (folders.some((folder) => folder.includes('**'))) {
72	      // Re-including the folders that '**' spans would bring back every
73	      // file below them, so they would be uploaded twice again.
74	      throw new Error(`'**' is only supported in the last segment: ${file}`);
75	    }
76	    folders.forEach((_, i) => included.add(folders.slice(0, i + 1).join('/')));
77	    included.add(file);
78	    included.add(file + '/**');
79	  }
80	  return ['**', ...[...included].map((glob) => '!' + glob)];
81	}
82	
83	const defaultBucketRemovalPolicy: RemovalPolicy = RemovalPolicy.DESTROY;
84	
85	/**
86	 * SPA infrastructure, which deploys spa content to an S3 bucket.
87	 *
88	 * The spa redirects from HTTP to HTTPS, uses a CloudFront distribution,
89	 * Route53 alias record,
90	 * and ACM certificate.
91	 */
92	export class SpaConstruct extends Construct {
93	  private bucketDeployments: BucketDeployment[] = [];
94	  private readonly bucket: Bucket;
95	  private readonly distribution: Distribution;
96	
97	  constructor(
98	    parent: Construct,
99	    private readonly spaName: string,
100	    props: SpaProps
101	  ) {
102	    super(parent, spaName);
103	    const removalPolicy: RemovalPolicy =
104	      props.bucketRemovalPolicy ?? defaultBucketRemovalPolicy;
105	    const {
106	      buildOutputPath,
107	      extraAllowedOrigins,
108	      noCacheFiles = [],
109	      cacheOverrides = [],
110	    } = props;
111	    const overrides: CacheOverride[] = [
112	      ...(noCacheFiles.length > 0
113	        ? [{ files: noCacheFiles, cacheControl: CacheControl.noCache() }]
114	        : []),
115	      ...cacheOverrides,
116	    ];
117	
118	    const { mainDomain, siteDomain } = this.extractDomains(props.domainName);
119	
120	    const zone = HostedZone.fromLookup(this, spaName, {
121	      privateZone: false,
122	      domainName: mainDomain,
123	    });
124	
125	    new CfnOutput(this, `${spaName}-Site:`, { value: 'https://' + siteDomain });
126	
127	    let certificate: Certificate;
128	
129	    if (mainDomain === siteDomain) {
130	      certificate = this.createCertificate(zone, mainDomain);
131	    } else {
132	      certificate = this.createCertificate(zone, mainDomain, siteDomain);
133	    }
134	
135	    this.bucket = this.createBucket(siteDomain, removalPolicy);
136	
137	    this.distribution = this.createDistribution(
138	      siteDomain,
139	      certificate,
140	      this.bucket,
141	      extraAllowedOrigins
142	    );
143	    this.createARecord(siteDomain, this.distribution, zone);
144	
145	    const indexAsset = Source.asset(buildOutputPath, {
146	      // glob ignore all but index.html
147	      exclude: ['**', '!index.html'],
148	    });
149	    this.bucketDeployments.push(
150	      this.createBucketDeployment(
151	        [indexAsset],
152	        CacheControl.noCache(),
153	        true,
154	        this.bucket,
155	        this.distribution
156	      )
157	    );
158	
159	    const deploymentAssets = Source.asset(buildOutputPath, {
160	      exclude: ['index.html', ...overrides.flatMap(({ files }) => files)],
161	    });
162	
163	    this.bucketDeployments.push(
164	      this.createBucketDeployment(
165	        [deploymentAssets],
166	        CacheControl.maxAge(Duration.days(365)),
167	        false,
168	        this.bucket,
169	        this.distribution
170	      )
171	    );
172	
173	    // Make sure that the index.html is deployed last, as it's needed to
174	    // serve the SPA so chain the deployments
175	    this.bucketDeployments[1].node.addDependency(this.bucketDeployments[0]);
176	
177	    for (const { files, cacheControl, contentType } of overrides) {
178	      this.addExtraAssets(
179	        [Source.asset(buildOutputPath, { exclude: onlyInclude(files) })],
180	        cacheControl,
181	        contentType
182	      );
183	    }
184	  }
185	
186	  /**
187	   * Add some additional assets to the bucket of the SPA
188	   */
189	  public addExtraAssets(
190	    assets: ISource[],
191	    cacheControl: CacheControl = CacheControl.maxAge(Duration.days(365)),
192	    contentType?: string
193	  ): void {
194	    const extraAssetsDeployment: BucketDeployment = this.createBucketDeployment(
195	      assets,
196	      cacheControl,
197	      false,
198	      this.bucket,
199	      this.distribution,
200	      contentType
201	    );
202	
203	    const latestDeployment: BucketDeployment | undefined =
204	      this.bucketDeployments.at(-1);
205	    if (latestDeployment) {
206	      extraAssetsDeployment.node.addDependency(latestDeployment);
207	    }
208	
209	    this.bucketDeployments.push(extraAssetsDeployment);
210	  }
211	
212	  private createBucket(
213	    siteDomain: string,
214	    removalPolicy: RemovalPolicy = RemovalPolicy.DESTROY
215	  ): Bucket {
216	    // Content bucket
217	    const siteBucket = new Bucket(this, `Bucket`, {
218	      websiteIndexDocument: 'index.html',
219	      websiteErrorDocument: 'index.html',
220	      bucketName: `${siteDomain}-spa-data`,
221	      publicReadAccess: false,
222	      blockPublicAccess: BlockPublicAccess.BLOCK_ALL,
223	      /**
224	       * The default removal policy is RETAIN, which means that cdk destroy will not attempt to delete
225	       * the new bucket, and it will remain in your account until manually deleted. By setting the policy to
226	       * DESTROY, cdk destroy will attempt to delete the bucket, but will error if the bucket is not empty.
227	       */
228	      removalPolicy: removalPolicy,
229	
230	      /**
231	       * For sample purposes only, if you create an S3 bucket then populate it, stack destruction fails.  This
232	       * setting will enable full cleanup of the demo.
233	       */
234	      autoDeleteObjects: removalPolicy === RemovalPolicy.DESTROY, // Danger not recommended for production code
235	    });
236	
237	    new CfnOutput(this, `${siteDomain}-Bucket`, {
238	      value: siteBucket.bucketName,
239	    });
240	    return siteBucket;
241	  }
242	
243	  private createCertificate(
244	    zone: IHostedZone,
245	    ...domainNames: string[]
246	  ): Certificate {
247	    const [mainDomain, ...restofDomains] = domainNames;
248	
249	    // TLS certificate
250	    const certificate = new Certificate(this, 'Certificate', {
251	      validation: CertificateValidation.fromDns(zone),
252	      domainName: mainDomain,
253	      subjectAlternativeNames: restofDomains,
254	    });
255	
256	    new CfnOutput(this, `${this.spaName}-sCertificate`, {
257	      value: certificate.certificateArn,
258	    });
259	    return certificate;
260	  }
261	
262	  private createDistribution(
263	    siteDomain: string,
264	    certificate: Certificate,
265	    siteBucket: IBucket,
266	    allowedOrigins: string[] = []
267	  ): Distribution {
268	    const responseHeadersPolicy = new ResponseHeadersPolicy(
269	      this,
270	      'ResponseHeadersPolicy',
271	      {
272	        corsBehavior: {
273	          accessControlAllowCredentials: false,
274	          accessControlAllowOrigins: [
275	            ...allowedOrigins,
276	            'https://' + siteDomain,
277	            'http://localhost',
278	            'http://127.0.0.1',
279	          ],
280	          accessControlAllowMethods: ['GET', 'HEAD', 'OPTIONS'],
281	          accessControlAllowHeaders: ['*'],
282	          originOverride: true,
283	        },
284	      }
285	    );
286	    // CloudFront distribution that provides HTTPS
287	    const distribution = new Distribution(this, 'Distribution', {
288	      certificate: certificate,
289	      defaultRootObject: 'index.html',
290	      domainNames: [siteDomain],
291	      httpVersion: HttpVersion.HTTP2_AND_3,
292	      minimumProtocolVersion: SecurityPolicyProtocol.TLS_V1_2_2021,
293	      errorResponses: [
294	        {
295	          httpStatus: 403,
296	          responseHttpStatus: 200,
297	          responsePagePath: '/index.html',
298	          ttl: Duration.minutes(30),
299	        },
300	      ],
301	      defaultBehavior: {
302	        responseHeadersPolicy,
303	        origin: S3BucketOrigin.withOriginAccessControl(siteBucket),
304	        compress: true,
305	        allowedMethods: AllowedMethods.ALLOW_GET_HEAD_OPTIONS,
306	        viewerProtocolPolicy: ViewerProtocolPolicy.REDIRECT_TO_HTTPS,
307	      },
308	    });
309	    new CfnOutput(this, `${this.spaName}-DistributionId`, {
310	      value: distribution.distributionId,
311	    });
312	    return distribution;
313	  }
314	
315	  private createARecord(
316	    siteDomain: string,
317	    distribution: Distribution,
318	    zone: IHostedZone
319	  ): void {
320	    // Route53 alias record for the CloudFront distribution
321	    new ARecord(this, 'SiteAliasRecord', {
322	      recordName: siteDomain,
323	      target: RecordTarget.fromAlias(new CloudFrontTarget(distribution)),
324	      zone,
325	    });
326	    new CfnOutput(this, `${this.spaName}-ARecord`, { value: siteDomain });
327	  }
328	
329	  private createBucketDeployment(
330	    sources: ISource[],
331	    cacheControl: CacheControl = CacheControl.maxAge(Duration.days(365)),
332	    prune: boolean,
333	    destinationBucket: IBucket,
334	    distribution: IDistribution,
335	    contentType?: string
336	  ): BucketDeployment {
337	    // Deploy site contents to S3 spaBucket
338	    return new BucketDeployment(
339	      this,
340	      'DeployWithInvalidation' + (this.bucketDeployments.length + 1),
341	      {
342	        sources,
343	        destinationBucket,
344	        distribution,
345	        prune,
346	        memoryLimit: 1024,
347	        distributionPaths: ['/*'],
348	        cacheControl: [cacheControl],
349	        ...(contentType ? { contentType } : {}),
350	      }
351	    );
352	  }
353	
354	  private extractDomains(domainName: string): {
355	    subDomainWildcard: string;
356	    mainDomain: string;
357	    siteDomain: string;
358	  } {
359	    // extract main domain
360	    const siteDomain = domainName;
361	    const mainDomain = domainName.split('.').slice(-2).join('.');
362	    const subDomainWildcard: string =
363	      mainDomain === siteDomain ? mainDomain : `*.${mainDomain}`;
364	
365	    // inform user about domain handling
366	    if (mainDomain !== siteDomain) {
367	      console.warn(
368	        `The domain ${siteDomain} is not a top level domain. The certificate will be created for *.${mainDomain}`
369	      );
370	    }
371	    return { siteDomain, mainDomain, subDomainWildcard };
372	  }
373	}
