1	import { App, Duration, RemovalPolicy } from 'aws-cdk-lib';
2	import { Match, Template } from 'aws-cdk-lib/assertions';
3	import { readdirSync } from 'fs';
4	import * as path from 'path';
5	import { vitest } from 'vitest';
6	import { SpaStack, SpaStackProps } from './spa/spa.stack';
7	import { CacheControl, Source } from 'aws-cdk-lib/aws-s3-deployment';
8	
9	// Mock the fromLookup method
10	vitest.mock('aws-cdk-lib/aws-route53', () => {
11	  return {
12	    HostedZone: {
13	      fromLookup: vitest.fn((domain: string) => ({ superZone: domain })),
14	    },
15	    RecordTarget: {
16	      fromAlias: vitest.fn(),
17	    },
18	    ARecord: vitest.fn(),
19	  };
20	});
21	const defaultTestProps: SpaStackProps = {
22	  env: {
23	    region: 'us-east-1',
24	    account: '123456789',
25	  },
26	  buildOutputPath: path.join(__dirname, '../../test-build-path'),
27	  domainName: 'test-domain.com',
28	};
29	describe('SpaCdkStack', () => {
30	  function testStackFactory(props: Partial<SpaStackProps> = defaultTestProps): {
31	    app: App;
32	    template: () => Template;
33	    stack: SpaStack;
34	  } {
35	    // GIVEN
36	    const app = new App();
37	
38	    // WHEN
39	    const stack = new SpaStack(app, 'TestSpaStack', {
40	      ...defaultTestProps,
41	      ...props,
42	    });
43	    const template = () => Template.fromStack(stack);
44	    return { stack, app, template };
45	  }
46	
47	  it('should match snapshot', () => {
48	    const { template } = testStackFactory();
49	    expect(template().toJSON()).toMatchSnapshot();
50	  });
51	
52	  it('should match snapshot setting bucket removal policy to retain', () => {
53	    const { template } = testStackFactory({
54	      bucketRemovalPolicy: RemovalPolicy.RETAIN_ON_UPDATE_OR_DELETE,
55	    });
56	    expect(template().toJSON()).toMatchSnapshot();
57	  });
58	
59	  it('should use the main domain name even if a subdomain is provided', () => {
60	    // given, when
61	    const { template } = testStackFactory({
62	      domainName: 'subdomain.test-domain.com',
63	    });
64	
65	    //then
66	    expect(template().toJSON()).toMatchSnapshot();
67	  });
68	
69	  it('should create an BucketDeployment for the buildOutputPath and index.html', () => {
70	    const { template } = testStackFactory();
71	    //then
72	    template().resourceCountIs('Custom::CDKBucketDeployment', 2);
73	    template().hasResourceProperties('Custom::CDKBucketDeployment', {
74	      SourceObjectKeys: Match.arrayEquals([Match.stringLikeRegexp('\\w+.zip')]),
75	    });
76	  });
77	
78	  it('should upload noCacheFiles with no-cache after the hashed bundles', () => {
79	    const { template } = testStackFactory({
80	      noCacheFiles: ['test-javascript-asset.js'],
81	    });
82	    //then
83	    template().resourceCountIs('Custom::CDKBucketDeployment', 3);
84	    const deployments = Object.values(
85	      template().findResources('Custom::CDKBucketDeployment')
86	    );
87	    const cacheControl = deployments.map(
88	      (deployment) => deployment.Properties.SystemMetadata['cache-control']
89	    );
90	    expect(cacheControl).toEqual(['no-cache', 'max-age=31536000', 'no-cache']);
91	    expect(deployments[2].DependsOn).toEqual(
92	      expect.arrayContaining([expect.stringMatching(/DeployWithInvalidation2/)])
93	    );
94	  });
95	
96	  it('should create an extra BucketDeployment when using addExtraAssets', () => {
97	    const { template, stack } = testStackFactory();
98	    stack.spa.addExtraAssets([
99	      Source.asset(path.join(__dirname, '../../extra-assets-path')),
100	    ]);
101	    //then
102	    expect(template().toJSON()).toMatchSnapshot();
103	  });
104	
105	  it('should create an extra BucketDeployment when using addExtraAssets with cache control', () => {
106	    const { template, stack } = testStackFactory();
107	    stack.spa.addExtraAssets(
108	      [Source.asset(path.join(__dirname, '../../extra-assets-path'))],
109	      CacheControl.maxAge(Duration.seconds(123456))
110	    );
111	    //then
112	    expect(template().toJSON()).toMatchSnapshot();
113	  });
114	
115	  it('should create an extra Custom::CDKBucketDeployment when using addExtraAssets', () => {
116	    const { template, stack } = testStackFactory();
117	
118	    //when
119	    stack.spa.addExtraAssets([
120	      Source.asset(path.join(__dirname, '../../extra-assets-path')),
121	    ]);
122	    //then
123	    template().resourceCountIs('Custom::CDKBucketDeployment', 3);
124	    template().hasResourceProperties('Custom::CDKBucketDeployment', {
125	      SourceObjectKeys: Match.arrayEquals([Match.stringLikeRegexp('\\w+.zip')]),
126	    });
127	  });
128	
129	  describe('cache overrides', () => {
130	    const nestedBuildPath = path.join(
131	      __dirname,
132	      '../../test-nested-build-path'
133	    );
134	
135	    function deployedFiles(props: Partial<SpaStackProps>): {
136	      cacheControl: string;
137	      contentType?: string;
138	      files: string[];
139	    }[] {
140	      const app = new App();
141	      const stack = new SpaStack(app, 'TestSpaStack', {
142	        ...defaultTestProps,
143	        buildOutputPath: nestedBuildPath,
144	        ...props,
145	      });
146	      const assemblyDir = app.synth().directory;
147	      return Object.values(
148	        Template.fromStack(stack).findResources('Custom::CDKBucketDeployment')
149	      ).map(({ Properties }) => ({
150	        cacheControl: Properties['SystemMetadata']['cache-control'],
151	        contentType: Properties['SystemMetadata']['content-type'],
152	        files: (Properties['SourceObjectKeys'] as string[]).flatMap((key) => {
153	          const assetDir = path.join(
154	            assemblyDir,
155	            'asset.' + key.replace(/\.zip$/, '')
156	          );
157	          return readdirSync(assetDir, { recursive: true, withFileTypes: true })
158	            .filter((entry) => entry.isFile())
159	            .map((entry) =>
160	              path
161	                .relative(assetDir, path.join(entry.parentPath, entry.name))
162	                .replaceAll(path.sep, '/')
163	            )
164	            .sort();
165	        }),
166	      }));
167	    }
168	
169	    it('should deploy every file once, with its own headers', () => {
170	      expect(
171	        deployedFiles({
172	          noCacheFiles: [
173	            'remoteEntry.json',
174	            'assets/federation.manifest*.json',
175	          ],
176	          cacheOverrides: [
177	            {
178	              files: ['fib-wasm/optimized.wasm'],
179	              cacheControl: CacheControl.maxAge(Duration.days(1)),
180	              contentType: 'application/wasm',
181	            },
182	          ],
183	        })
184	      ).toEqual([
185	        { cacheControl: 'no-cache', files: ['index.html'] },
186	        {
187	          cacheControl: 'max-age=31536000',
188	          files: ['assets/logo.svg', 'main.js'],
189	        },
190	        {
191	          cacheControl: 'no-cache',
192	          files: ['assets/federation.manifest.json', 'remoteEntry.json'],
193	        },
194	        {
195	          cacheControl: 'max-age=86400',
196	          contentType: 'application/wasm',
197	          files: ['fib-wasm/optimized.wasm'],
198	        },
199	      ]);
200	    });
