189	  public addExtraAssets(
190	    assets: ISource[],
191	    cacheControl: CacheControl = CacheControl.maxAge(Duration.days(365)),
192	    contentType?: string
193	  ): void {
194	    const extraAssetsDeployment: BucketDeployment = this.createBucketDeployment(
195	      assets,
196	      cacheControl,
197	      false,
198	      this.bucket,
199	      this.distribution,
200	      contentType
201	    );
202	
203	    const latestDeployment: BucketDeployment | undefined =
204	      this.bucketDeployments.at(-1);
205	    if (latestDeployment) {
206	      extraAssetsDeployment.node.addDependency(latestDeployment);
207	    }
208	
209	    this.bucketDeployments.push(extraAssetsDeployment);
210	  }
211	
212	  private createBucket(
213	    siteDomain: string,
214	    removalPolicy: RemovalPolicy = RemovalPolicy.DESTROY
215	  ): Bucket {
216	    // Content bucket
217	    const siteBucket = new Bucket(this, `Bucket`, {
218	      websiteIndexDocument: 'index.html',
219	      websiteErrorDocument: 'index.html',
220	      bucketName: `${siteDomain}-spa-data`,
221	      publicReadAccess: false,
222	      blockPublicAccess: BlockPublicAccess.BLOCK_ALL,
223	      /**
224	       * The default removal policy is RETAIN, which means that cdk destroy will not attempt to delete
225	       * the new bucket, and it will remain in your account until manually deleted. By setting the policy to
226	       * DESTROY, cdk destroy will attempt to delete the bucket, but will error if the bucket is not empty.
227	       */
228	      removalPolicy: removalPolicy,
229	
230	      /**
231	       * For sample purposes only, if you create an S3 bucket then populate it, stack destruction fails.  This
232	       * setting will enable full cleanup of the demo.
233	       */
234	      autoDeleteObjects: removalPolicy === RemovalPolicy.DESTROY, // Danger not recommended for production code
235	    });
236	
237	    new CfnOutput(this, `${siteDomain}-Bucket`, {
238	      value: siteBucket.bucketName,
239	    });
240	    return siteBucket;
241	  }
242	
243	  private createCertificate(
244	    zone: IHostedZone,
245	    ...domainNames: string[]
246	  ): Certificate {
247	    const [mainDomain, ...restofDomains] = domainNames;
248	
249	    // TLS certificate
250	    const certificate = new Certificate(this, 'Certificate', {
251	      validation: CertificateValidation.fromDns(zone),
252	      domainName: mainDomain,
253	      subjectAlternativeNames: restofDomains,
254	    });
255	
256	    new CfnOutput(this, `${this.spaName}-sCertificate`, {
257	      value: certificate.certificateArn,
258	    });
259	    return certificate;
260	  }
261	
262	  private createDistribution(
263	    siteDomain: string,
264	    certificate: Certificate,
265	    siteBucket: IBucket,
266	    allowedOrigins: string[] = []
267	  ): Distribution {
268	    const responseHeadersPolicy = new ResponseHeadersPolicy(
269	      this,
270	      'ResponseHeadersPolicy',
271	      {
272	        corsBehavior: {
273	          accessControlAllowCredentials: false,
274	          accessControlAllowOrigins: [
275	            ...allowedOrigins,
276	            'https://' + siteDomain,
277	            'http://localhost',
278	            'http://127.0.0.1',
279	          ],
280	          accessControlAllowMethods: ['GET', 'HEAD', 'OPTIONS'],
281	          accessControlAllowHeaders: ['*'],
282	          originOverride: true,
283	        },
284	      }
285	    );
286	    // CloudFront distribution that provides HTTPS
287	    const distribution = new Distribution(this, 'Distribution', {
288	      certificate: certificate,
289	      defaultRootObject: 'index.html',
290	      domainNames: [siteDomain],
291	      httpVersion: HttpVersion.HTTP2_AND_3,
292	      minimumProtocolVersion: SecurityPolicyProtocol.TLS_V1_2_2021,
293	      errorResponses: [
294	        {
295	          httpStatus: 403,
296	          responseHttpStatus: 200,
297	          responsePagePath: '/index.html',
298	          ttl: Duration.minutes(30),
299	        },
300	      ],
301	      defaultBehavior: {
302	        responseHeadersPolicy,
303	        origin: S3BucketOrigin.withOriginAccessControl(siteBucket),
304	        compress: true,
305	        allowedMethods: AllowedMethods.ALLOW_GET_HEAD_OPTIONS,
306	        viewerProtocolPolicy: ViewerProtocolPolicy.REDIRECT_TO_HTTPS,
307	      },
308	    });
309	    new CfnOutput(this, `${this.spaName}-DistributionId`, {
310	      value: distribution.distributionId,
311	    });
312	    return distribution;
313	  }
314	
315	  private createARecord(
316	    siteDomain: string,
317	    distribution: Distribution,
318	    zone: IHostedZone
319	  ): void {
320	    // Route53 alias record for the CloudFront distribution
321	    new ARecord(this, 'SiteAliasRecord', {
322	      recordName: siteDomain,
323	      target: RecordTarget.fromAlias(new CloudFrontTarget(distribution)),
324	      zone,
325	    });
326	    new CfnOutput(this, `${this.spaName}-ARecord`, { value: siteDomain });
327	  }
328	
329	  private createBucketDeployment(
330	    sources: ISource[],
331	    cacheControl: CacheControl = CacheControl.maxAge(Duration.days(365)),
332	    prune: boolean,
333	    destinationBucket: IBucket,
334	    distribution: IDistribution,
335	    contentType?: string
336	  ): BucketDeployment {
337	    // Deploy site contents to S3 spaBucket
338	    return new BucketDeployment(
339	      this,
340	      'DeployWithInvalidation' + (this.bucketDeployments.length + 1),
341	      {
342	        sources,
343	        destinationBucket,
344	        distribution,
345	        prune,
346	        memoryLimit: 1024,
347	        distributionPaths: ['/*'],
348	        cacheControl: [cacheControl],
349	        ...(contentType ? { contentType } : {}),
350	      }
351	    );
352	  }
353	
354	  private extractDomains(domainName: string): {
355	    subDomainWildcard: string;
356	    mainDomain: string;
357	    siteDomain: string;
358	  } {
359	    // extract main domain
360	    const siteDomain = domainName;
361	    const mainDomain = domainName.split('.').slice(-2).join('.');
362	    const subDomainWildcard: string =
363	      mainDomain === siteDomain ? mainDomain : `*.${mainDomain}`;
364	
365	    // inform user about domain handling
366	    if (mainDomain !== siteDomain) {
367	      console.warn(
368	        `The domain ${siteDomain} is not a top level domain. The certificate will be created for *.${mainDomain}`
369	      );
370	    }
371	    return { siteDomain, mainDomain, subDomainWildcard };
372	  }
373	}
